class PassportIn(BaseModel):
    customer_name: str
    contact: str = ""
    email: str = ""
    skin_type: str = "Combination"
    hair_type: str = "Wavy"
    lifestyle_factors: str = ""
    allergies: str = ""
    beauty_goals: str = ""
    preferred_products: str = ""

class SkinIn(BaseModel):
    passport_id: Optional[int] = None
    score: int = Field(ge=0, le=100)
    skin_type: str
    sun_exposure: str
    concerns: str = ""
    android_microscope_used: bool = False

class HairIn(BaseModel):
    passport_id: Optional[int] = None
    score: int = Field(ge=0, le=100)
    hair_type: str
    scalp_condition: str
    concerns: str = ""
    face_shape: str = "Oval"
    skin_tone: str = "Medium"

class FootIn(BaseModel):
    passport_id: Optional[int] = None
    score: int = Field(ge=0, le=100)
    heel_condition: str
    pain_level: str
    concerns: str = ""
    android_microscope_used: bool = False

class MicroscopeIn(BaseModel):
    passport_id: Optional[int] = None
    device_name: str = "Jiusion 2K HD 2560x1440P USB Digital Microscope"
    magnification: str = "40X-1000X"
    analysis_mode: Literal["Skin","Hair/Scalp","Foot"] = "Skin"
    pore_count: int
    pore_size: float
    bacteria_level: Literal["Low","Moderate","High"]
    texture_severity: Literal["Low","Moderate","High"]
    findings_note: str = ""
    scalp_condition: str = "Balanced"

class BridalIn(BaseModel):
    passport_id: Optional[int] = None
    outfit_type: Literal["Saree","Lehenga"]
    outfit_color: str
    skin_tone: Literal["Fair","Medium","Olive","Deep"]
    event_time: Literal["Morning","Evening","Night"]
    preferences: str = ""

class ChatIn(BaseModel):
    message: str
    language: Literal["en","ta"] = "ta"

TREATMENT_INCIDENTS = [
    {"id":"INC-SKIN-001","category":"Skin","trigger":"chemical peel on sensitive skin without patch test","risk_tags":["sensitive","peel","active treatment"],"warning":"Patch test and barrier-first protocol required before active treatments."},
    {"id":"INC-SKIN-002","category":"Skin","trigger":"strong detan or bleach on reactive skin","risk_tags":["tan","sensitive","bleach"],"warning":"Avoid harsh bleach / strong detan when sensitivity or irritation is present."},
    {"id":"INC-HAIR-001","category":"Hair","trigger":"coloring over damaged hair without strand test","risk_tags":["damage","color","bleach"],"warning":"Strand test and bond-repair prep required before color / bleach services."},
    {"id":"INC-HAIR-002","category":"Hair","trigger":"hot tools on weak hair shaft","risk_tags":["breakage","heat","frizz"],"warning":"Reduce heat styling and prioritize repair rituals before high-heat finishing."},
    {"id":"INC-FOOT-001","category":"Foot","trigger":"aggressive scrub on cracked heel or pain area","risk_tags":["crack","pain","dryness"],"warning":"Avoid aggressive scrubbing on cracked / painful foot areas."}
]

def face_shape_haircut(face_shape: str, hair_type: str):
    fs=(face_shape or "").lower(); ht=(hair_type or "").lower()
    suggestions={"oval":["Soft layers","Long bob","Curtain bangs"],"round":["Long layers","Face-framing lob","Side-part volume cut"],"square":["Textured layers","Soft waves cut","Feathered shoulder cut"],"heart":["Chin-length bob","Collarbone layers","Side-swept bangs"],"diamond":["Layered lob","Soft fringe cut","Medium textured cut"],"oblong":["Shoulder-length waves","Fringe with layers","Volume bob"]}
    base=suggestions.get(fs,["Soft layers","Balanced lob","Face-framing cut"])
    if "curly" in ht or "coily" in ht: base=[x+" for curl definition" for x in base]
    return {"haircut_suggestions":base,"why":f"Selected to balance {face_shape} proportions and suit {hair_type} texture."}

def hair_color_by_skin_tone(skin_tone: str):
    tone=(skin_tone or "").lower()
    if tone=="fair": colors=["Soft brown","Ash brown","Rose brown","Burgundy accents"]
    elif tone=="olive": colors=["Chocolate brown","Chestnut","Copper brown","Deep burgundy"]
    elif tone=="deep": colors=["Espresso","Mocha brown","Warm mahogany","Rich plum brown"]
    else: colors=["Caramel brown","Warm chocolate","Cinnamon brown","Soft burgundy"]
    return {"recommended_hair_colors":colors,"note":"Shade selection should also consider damage level and maintenance comfort."}

def analyze_skin(data: SkinIn):
    issues=[]; services=[]; home=[]; mods=[]; risk="Low"
    if data.score < 70:
        issues += ["Barrier weakness","Visible dullness","Uneven texture"]
        services += ["Calming facial","Barrier repair treatment","Hydration rescue therapy"]
        home += ["Ceramide moisturizer","Gentle cleanser","Daily SPF 50"]
        mods += ["Reduce harsh scrubbing","Increase hydration","Use barrier-safe products"]
        risk="Moderate"
    elif data.score < 85:
        issues += ["Mild dehydration","Glow imbalance"]
        services += ["Hydration facial","Brightening therapy","Maintenance peel"]
        home += ["Hydration serum","SPF","Weekly recovery mask"]
        mods += ["Consistent sunscreen use","Balanced sleep cycle"]
    else:
        issues += ["Healthy skin baseline","Good glow retention"]
        services += ["Glow maintenance facial","Radiance booster"]
        home += ["Light serum","Daily sunscreen","Hydration support"]
        mods += ["Continue maintenance","Protect from heavy sun exposure"]
    lc=data.concerns.lower()
    if data.skin_type=="Oily" or "acne" in lc or "oil" in lc:
        services.insert(0,"Clarifying skin treatment"); home.insert(0,"Oil-control cleanser"); mods.append("Avoid comedogenic products")
    if data.skin_type=="Sensitive" or "sensitive" in lc:
        services.insert(0,"Patch-test based soothing facial"); home.insert(0,"Fragrance-free barrier cream"); risk="Moderate"
    if "pigment" in lc or "tan" in lc:
        services.append("Pigmentation correction program"); home.append("Niacinamide / brightening routine")
    warnings=[]
    for inc in TREATMENT_INCIDENTS:
        if inc["category"]=="Skin" and (any(tag in lc for tag in inc["risk_tags"]) or data.skin_type.lower()=="sensitive"):
            warnings.append(inc["warning"])
    if not warnings: warnings=["Proceed with standard consultation and patch testing as needed."]
    return {"title":"Skin Analysis Report","health_score":data.score,"issues":issues,"services":services[:5],"facial_recommendations":services[:3],"homecare":home[:5],"lifestyle_modifications":mods[:4],"risk_level":risk,"warnings":list(dict.fromkeys(warnings)),"follow_up_days":14 if risk=="Moderate" else 30,"android_microscope_used":data.android_microscope_used}

def analyze_hair(data: HairIn):
    issues=[]; services=[]; home=[]; risk="Low"
    if data.score < 70:
        issues += ["Breakage risk","Scalp imbalance","Visible dryness"]
        services += ["Protein repair ritual","Scalp therapy","Intense hair spa"]
        home += ["Mild shampoo","Scalp serum","Heat protection","Weekly mask"]
        risk="Moderate"
    elif data.score < 85:
        issues += ["Mild frizz","Mid-length care needed"]
        services += ["Nourish spa","Scalp balancing ritual","Smoothening care"]
        home += ["Leave-in serum","Weekly mask","Heat protectant"]
    else:
        issues += ["Good strength","Good scalp baseline"]
        services += ["Gloss therapy","Color-safe shine ritual"]
        home += ["Color-safe cleanser","Light serum"]
    lc=data.concerns.lower()
    if data.scalp_condition=="Flaky" or "dandruff" in lc:
        services.insert(0,"Anti-flake scalp detox"); home.insert(0,"Scalp hygiene tonic")
    if "hair fall" in lc:
        services.insert(0,"Hair fall control therapy"); home.insert(0,"Root-strength serum"); risk="Moderate"
    if "damage" in lc or "color" in lc or "bleach" in lc:
        services.append("Bond repair treatment")
    haircut=face_shape_haircut(data.face_shape,data.hair_type)
    colors=hair_color_by_skin_tone(data.skin_tone)
    return {"title":"Hair Analysis Report","health_score":data.score,"issues":issues,"services":services[:5],"homecare":home[:5],"risk_level":risk,"follow_up_days":21 if risk=="Moderate" else 30,"haircut_recommendations":haircut["haircut_suggestions"],"haircut_why":haircut["why"],"hair_color_recommendations":colors["recommended_hair_colors"],"color_note":colors["note"]}

def analyze_foot(data: FootIn):
    issues=[]; services=[]; home=[]; caution="No critical warning."
    if data.score < 70:
        issues += ["Heel crack risk","Dry barrier","Foot comfort reduction"]
        services += ["Repair pedicure","Heel restoration therapy","Protective foot care"]
        home += ["Night heel balm","Cotton socks after moisturizing","Avoid harsh scrubs"]
        caution="Escalate if diabetic foot or pain persists."
    elif data.score < 85:
        issues += ["Dry heel tendency","Maintenance required"]
        services += ["Hydration pedicure","Heel softening therapy"]
        home += ["Hydration cream","Gentle exfoliation","Closed footwear in dusty areas"]
    else:
        issues += ["Healthy foot baseline"]
        services += ["Luxury pedicure","Maintenance hydration ritual"]
        home += ["Weekly hydration","Regular hygiene care"]
    lc=data.concerns.lower()
    if data.heel_condition=="Cracked" or "crack" in lc:
        services.insert(0,"Intensive crack-heal session"); caution="Regular follow-up required until heel surface improves."
    if data.pain_level in ["Moderate","High"]:
        caution="Check pain source before pressure-based service."
    if "diabetic" in lc: caution="Medical caution advised before aggressive foot procedures."
    return {"title":"Foot Analysis Report","care_score":data.score,"issues":issues,"services":services[:5],"homecare":home[:5],"caution":caution,"follow_up_days":14 if ('follow-up' in caution.lower() or 'medical' in caution.lower() or 'escalate' in caution.lower()) else 30,"android_microscope_used":data.android_microscope_used}

def microscope_analysis(data: MicroscopeIn):
    severity="Low"
    if data.pore_count > 140 or data.pore_size > 45 or data.bacteria_level=="High" or data.texture_severity=="High":
        severity="High"
    elif data.pore_count > 90 or data.pore_size > 30 or data.bacteria_level=="Moderate" or data.texture_severity=="Moderate":
        severity="Moderate"
    findings=[f"Pore count detected: {data.pore_count}",f"Average pore size: {data.pore_size} μm",f"Bacteria level: {data.bacteria_level}",f"Texture severity: {data.texture_severity}"]
    if data.findings_note: findings.append(data.findings_note)
    if data.analysis_mode=="Hair/Scalp":
        if data.bacteria_level=="High" or data.texture_severity=="High" or data.scalp_condition=="Flaky":
            scalp_risk="Moderate"; recommendations=["Scalp detox with microscope follow-up","Anti-flake / hygiene care","Low-irritation scalp serum"]
        else:
            scalp_risk="Low"; recommendations=["Routine scalp hygiene maintenance","Monthly scalp therapy","Balanced cleansing schedule"]
    elif data.analysis_mode=="Foot":
        scalp_risk="N/A"; recommendations=["Pressure-zone hydration care","Gentle repair protocol","Follow-up foot hygiene review"]
    else:
        scalp_risk="N/A"; recommendations=["Deep cleansing protocol","Pore-refining service","Sebum control care"] if severity!="Low" else ["Routine maintenance","Mild clarifying care"]
    days=14 if severity=="High" else 21 if severity=="Moderate" else 30
    return {"title":"Microscope AI Report","analysis_mode":data.analysis_mode,"severity":severity,"findings":findings,"recommendations":recommendations,"scalp_risk":scalp_risk,"follow_up_date":(datetime.now()+timedelta(days=days)).date().isoformat()}

