def salon_intelligence():
    conn=get_db(); cur=conn.cursor()
    staff=[dict(x) for x in cur.execute("SELECT * FROM staff_profiles").fetchall()]
    skills=[dict(x) for x in cur.execute("SELECT * FROM skill_assessments").fetchall()]
    audits=[dict(x) for x in cur.execute("SELECT * FROM service_audits").fetchall()]
    revenues=[dict(x) for x in cur.execute("SELECT * FROM revenue_records").fetchall()]
    conn.close()
    total_revenue=sum(r["amount"] for r in revenues) if revenues else 0
    avg_rating=round(sum(s["avg_rating"] for s in staff)/len(staff),2) if staff else 0
    avg_quality=round(sum(a["quality_score"] for a in audits)/len(audits),1) if audits else 0
    skill_distribution={"L1":0,"L2":0,"L3":0}
    for s in staff: skill_distribution[s["skill_level"]] = skill_distribution.get(s["skill_level"],0)+1
    lowest=min(skills,key=lambda x:x["score"]) if skills else None
    top_staff=sorted(staff,key=lambda x:(x["monthly_revenue"],x["avg_rating"]),reverse=True)[:4]
    franchise_revenue={}
    for r in revenues: franchise_revenue[r["location"]] = franchise_revenue.get(r["location"],0)+r["amount"]
    return {"total_revenue":total_revenue,"avg_rating":avg_rating,"avg_quality":avg_quality,"skill_distribution":skill_distribution,"priority_training_need":lowest["improvement_area"] if lowest else "No gap identified","priority_staff":lowest["staff_name"] if lowest else "N/A","top_staff":top_staff,"franchise_revenue":franchise_revenue,"insights":["Convert training, assessments, audits, feedback, and revenue into one decision layer.","Top-performing staff combine stronger revenue with high customer rating.","L1 → L3 growth planning should prioritize current low-score categories first.","Beauty Passport and personalized journeys improve retention and lifetime value."]}

CHAT_TRAINING=[("I want to book appointment","booking"),("book facial tomorrow","booking"),("slot for bridal trial","booking"),("facial price","pricing"),("hair spa cost","pricing"),("bridal package rate","pricing"),("suggest haircut for round face","hair"),("hair fall problem","hair"),("dandruff and scalp issue","hair"),("hair color suggestion for my skin tone","hair"),("skin acne help","skin"),("facial for pigmentation","skin"),("tanning and dullness treatment","skin"),("bridal makeup needed","bridal"),("lehenga makeup suggestion","bridal"),("saree bridal look","bridal"),("pedicure for cracked heel","foot"),("foot pain and dry heel","foot"),("microscope skin analysis","microscope"),("jiusion microscope scalp analysis","microscope"),("thanks","thanks"),("thank you","thanks"),("வணக்கம்","greeting"),("புக்கிங் செய்ய வேண்டும்","booking"),("விலை என்ன","pricing"),("முடி உதிர்வு","hair"),("தோல் பராமரிப்பு","skin"),("மணமகள் மேக்கப்","bridal"),("கால் crack care","foot"),("மைக்ரோஸ்கோப் analysis","microscope"),("நன்றி","thanks")]
if SKLEARN_OK:
    _texts=[x[0] for x in CHAT_TRAINING]; _labels=[x[1] for x in CHAT_TRAINING]
    CHAT_VEC=TfidfVectorizer(ngram_range=(1,2)); X=CHAT_VEC.fit_transform(_texts); CHAT_MODEL=LogisticRegression(max_iter=1000); CHAT_MODEL.fit(X,_labels)

def intent_predict(message:str)->str:
    if SKLEARN_OK:
        try: return CHAT_MODEL.predict(CHAT_VEC.transform([message]))[0]
        except Exception: pass
    m=message.lower()
    if "book" in m or "புக்கிங்" in m: return "booking"
    if "price" in m or "விலை" in m: return "pricing"
    if any(x in m for x in ["hair","முடி","dandruff","hair fall","scalp"]): return "hair"
    if any(x in m for x in ["skin","தோல்","facial","acne","pigment","tanning"]): return "skin"
    if any(x in m for x in ["bridal","மண","lehenga","saree","makeup"]): return "bridal"
    if any(x in m for x in ["foot","கால்","pedicure","heel"]): return "foot"
    if any(x in m for x in ["microscope","மைக்ரோஸ்கோப்","jiusion","pore"]): return "microscope"
    if any(x in m for x in ["thanks","thank","நன்றி"]): return "thanks"
    if any(x in m for x in ["hello","hi","வணக்கம்","ஹலோ"]): return "greeting"
    return "general"

def salon_chat(message:str, lang:str):
    intent=intent_predict(message)
    close_en=" Thank you for choosing Naturals. We look forward to serving you."
    close_ta=" நேச்சுரல்ஸ் தேர்வு செய்ததற்கு நன்றி. உங்களுக்கு சேவை செய்ய ஆவலாக உள்ளோம்."
    responses={
        "greeting":{"en":"Welcome to Naturals. I can help with bookings, services, bridal consultation, skin, hair, foot care, pricing guidance, and aftercare.","ta":"நேச்சுரல்ஸுக்கு வரவேற்கிறோம். புக்கிங், சேவைகள், bridal consultation, skin, hair, foot care, விலை வழிகாட்டல், மற்றும் aftercare பற்றி உதவலாம்."},
        "booking":{"en":"For booking, please share the service name, preferred date, and preferred time. I can also guide you to premium slots, bridal trials, or regular appointments.","ta":"புக்கிங் செய்ய சேவை பெயர், தேதி, நேரம் சொல்லுங்கள். Premium slot, bridal trial, அல்லது regular appointment எது பொருத்தமோ அதற்கும் வழிகாட்டுகிறேன்."},
        "pricing":{"en":"Pricing depends on the service, branch, and package level. Please tell me whether you need facial, hair spa, bridal, pedicure, hair color, or scalp service so I can guide you to the right package type.","ta":"சேவை விலை branch, service category, மற்றும் package level ஆகியவற்றைப் பொறுத்தது. Facial, hair spa, bridal, pedicure, hair color, அல்லது scalp service எது வேண்டும் என்று சொல்லுங்கள்; சரியான package வகையை வழிகாட்டுகிறேன்."},
        "skin":{"en":"For skin guidance, please tell me whether the concern is acne, tanning, pigmentation, sensitivity, dullness, or dehydration. I can suggest the right facial, treatment intensity, follow-up timeline, and home-care plan.","ta":"Skin guidance க்கு acne, tanning, pigmentation, sensitivity, dullness, அல்லது dehydration இருக்கிறதா என்று சொல்லுங்கள். அதன்படி facial, treatment intensity, follow-up timeline, மற்றும் home-care plan சொல்கிறேன்."},
        "hair":{"en":"For hair guidance, please tell me whether the concern is hair fall, frizz, dandruff, scalp sensitivity, breakage, or color damage. I can suggest spa, scalp therapy, haircut direction by face shape, color recommendations by skin tone, and aftercare.","ta":"Hair guidance க்கு hair fall, frizz, dandruff, scalp sensitivity, breakage, அல்லது color damage இருக்கிறதா என்று சொல்லுங்கள். அதன்படி spa, scalp therapy, face shape haircut suggestion, skin tone hair color suggestion, மற்றும் aftercare சொல்லுகிறேன்."},
        "foot":{"en":"For foot care, please tell me whether the concern is dryness, cracked heels, pain, discomfort, or dark ankles. I can guide you toward repair pedicure, heel restoration, hydration care, and home-care.","ta":"Foot care க்கு dryness, cracked heels, pain, discomfort, அல்லது dark ankles எது concern என்று சொல்லுங்கள். அதன்படி repair pedicure, heel restoration, hydration care, மற்றும் home-care வழிகாட்டுகிறேன்."},
        "bridal":{"en":"For bridal consultation, please share outfit type, color, skin tone, wedding timing, and whether you want traditional, soft glam, minimal, fusion, or luxurious styling. I can suggest prelooks, jewellery, makeup palette, hairstyle, and trial planning.","ta":"Bridal consultation க்கு outfit type, color, skin tone, event time, மற்றும் traditional / soft glam / minimal / fusion / luxurious style எது வேண்டும் என்று சொல்லுங்கள். அதன்படி prelooks, jewellery, makeup palette, hairstyle, trial planning சொல்லுகிறேன்."},
        "microscope":{"en":"Yes, this platform supports Android-connected Jiusion microscope analysis. You can capture pore, scalp, skin, or foot surface data and submit pore count, pore size, bacteria level, and texture severity for AI-assisted treatment guidance.","ta":"ஆம், இந்த platform Android-connected Jiusion microscope analysis-ஐ support செய்கிறது. Pore, scalp, skin, அல்லது foot surface data capture செய்து pore count, pore size, bacteria level, texture severity கொண்டு AI-assisted treatment guidance பெறலாம்."},
        "thanks":{"en":"Thank you for choosing Naturals. Please visit us again.","ta":"நேச்சுரல்ஸ் தேர்வு செய்ததற்கு நன்றி. மீண்டும் வருக."},
        "general":{"en":"I can help with bookings, pricing guidance, bridal planning, skin analysis, hair analysis, foot care, microscope-based consultation, spa services, and aftercare. Please tell me what you need.","ta":"புக்கிங், விலை வழிகாட்டல், bridal planning, skin analysis, hair analysis, foot care, microscope-based consultation, spa services, மற்றும் aftercare பற்றி உதவலாம். உங்களுக்கு என்ன வேண்டும் என்று சொல்லுங்கள்."},
    }
    if intent=="thanks": return {"intent":intent,"reply":responses[intent][lang]}
    return {"intent":intent,"reply":responses[intent][lang] + (close_ta if lang=="ta" else close_en)}

