@app.get("/api/v2/analysis/history/{passport_id}")
def analysis_history(passport_id:int):
    conn=get_db()
    skin=[dict(x) for x in conn.execute("SELECT * FROM skin_analysis WHERE passport_id=? ORDER BY id DESC",(passport_id,)).fetchall()]
    hair=[dict(x) for x in conn.execute("SELECT * FROM hair_analysis WHERE passport_id=? ORDER BY id DESC",(passport_id,)).fetchall()]
    foot=[dict(x) for x in conn.execute("SELECT * FROM foot_analysis WHERE passport_id=? ORDER BY id DESC",(passport_id,)).fetchall()]
    conn.close(); return {"skin":skin,"hair":hair,"foot":foot}

