@app.get("/api/v2/skills/gaps")
def skills_gaps():
    conn=get_db(); rows=[dict(x) for x in conn.execute("SELECT * FROM skill_assessments ORDER BY score ASC").fetchall()]; conn.close()
    return {"priority_gaps":rows[:5],"growth_pathway":{"L1":"Basic service training, product knowledge, hygiene & safety","L2":"Advanced techniques, quality optimization, diagnosis, consultation","L3":"Mentoring, audits, innovation, strategic planning"}}

@app.get("/api/v2/revenue/summary")
def revenue_summary():
    conn=get_db(); rows=conn.execute("SELECT location, service_type, amount, staff_name FROM revenue_records").fetchall(); conn.close()
    total=sum(r["amount"] for r in rows); by_loc={}; by_service={}
    for r in rows:
        by_loc[r["location"]]=by_loc.get(r["location"],0)+r["amount"]; by_service[r["service_type"]]=by_service.get(r["service_type"],0)+r["amount"]
    return {"total_revenue":total,"by_location":by_loc,"by_service":by_service}

@app.get("/api/v2/audits/list")
def audits_list():
    conn=get_db(); rows=[dict(x) for x in conn.execute("SELECT * FROM service_audits ORDER BY id DESC").fetchall()]; conn.close(); return rows

@app.get("/api/v2/feedback/summary")
def feedback_summary():
    conn=get_db(); rows=conn.execute("SELECT service_quality, repeat_likelihood FROM customer_feedback").fetchall(); conn.close()
    if not rows: return {"avg_quality":0,"avg_repeat_likelihood":0}
    return {"avg_quality":round(sum(r["service_quality"] for r in rows)/len(rows),2),"avg_repeat_likelihood":round(sum(r["repeat_likelihood"] for r in rows)/len(rows),2)}

