@app.get("/api/v2/dashboard/metrics")
def dashboard_metrics():
    conn=get_db(); total_profiles=conn.execute("SELECT COUNT(*) FROM beauty_passports").fetchone()[0]
    analysis_count=conn.execute("SELECT COUNT(*) FROM skin_analysis").fetchone()[0]+conn.execute("SELECT COUNT(*) FROM hair_analysis").fetchone()[0]+conn.execute("SELECT COUNT(*) FROM foot_analysis").fetchone()[0]
    conn.close(); return {"customer_metrics":{"total_profiles":total_profiles,"analysis_count":analysis_count},"business_metrics":salon_intelligence()}

